package net.civeira.phylax.features.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class IdTokenEncryptedResponseAlgVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property id token encrypted response alg of oauth client ")
  void test_id_token_encrypted_response_alg_v_o_builder() {
    Assertions.assertFalse(
        IdTokenEncryptedResponseAlgVO.nullValue().getIdTokenEncryptedResponseAlg().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        IdTokenEncryptedResponseAlgVO.tryFrom(null).getIdTokenEncryptedResponseAlg().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        IdTokenEncryptedResponseAlgVO.from("one").getIdTokenEncryptedResponseAlg().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> IdTokenEncryptedResponseAlgVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]",
        IdTokenEncryptedResponseAlgVO.from("one").toString());
  }
}
